const $=id=>document.getElementById(id),modal=$('modal'),body=$('content'),key='cau.flora.records.v1';
const symbols={camera:'<path d="M3 8h4l2-3h6l2 3h4v12H3z"/><circle cx="12" cy="13" r="3.5"/>',image:'<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8" cy="9" r="1"/><path d="m4 17 5-5 4 3 3-4 5 6"/>',leaf:'<path d="M19 4C8 3 3 8 6 15c4 7 15 1 13-11Z M4 21 15 9"/>'};
const icon=k=>'<svg class="ico" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round">'+symbols[k]+'</svg>';
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
function records(){try{let v=JSON.parse(localStorage.getItem(key)||'[]');return v.filter(r=>plants[r.id]&&typeof r.photo==='string'&&r.photo.startsWith('data:image/'))}catch{return []}}
function escapeHtml(value){let s=document.createElement('span');s.textContent=value;return s.innerHTML}
function show(html){body.innerHTML=html;if(!modal.open)modal.showModal();modal.scrollTop=0}
$('close').onclick=()=>modal.close();modal.onclick=e=>{if(e.target===modal&&!(e.clientX>=modal.getBoundingClientRect().left&&e.clientX<=modal.getBoundingClientRect().right&&e.clientY>=modal.getBoundingClientRect().top&&e.clientY<=modal.getBoundingClientRect().bottom))modal.close()};
function cardCaption(id){let p=plants[id];return '<div class="cardFoot"><div><h3>'+p.name+'</h3><i class="latin">'+p.latin+'</i></div><span class="mark">'+icon('leaf')+'</span></div>'}
plants.forEach((p,id)=>{let b=document.createElement('button');b.className='card';b.innerHTML='<div class="art"><canvas></canvas><span class="tag">'+p.family+'</span></div>'+cardCaption(id);$('atlas').append(b);plate(b.querySelector('canvas'),id);b.onclick=()=>{show('<canvas class="detailArt"></canvas><div class="body"><div class="eyebrow">'+p.family+'</div><h2>'+p.name+'</h2><i>'+p.latin+'</i><p>'+p.note+'</p><button class="primary" id="sample">用示例叶片体验识别</button></div>');plate(body.querySelector('canvas'),id);$('sample').onclick=()=>result(sampleLeaf(id),true)}});
plate($('heroCanvas'),0,true);
function route(){let garden=location.hash==='#garden';$('explore').hidden=garden;$('garden').hidden=!garden;$('ne').classList.toggle('active',!garden);$('ng').classList.toggle('active',garden);let list=records();$('qty').textContent=list.length;$('records').replaceChildren();if(!list.length)$('records').innerHTML='<div class="empty"><h2>你的第一株植物会是什么？</h2><p>拍下叶片，确认名字后就能在这里找到它。</p><button class="light" id="first">拍照识植</button></div>';if($('first'))$('first').onclick=guide;
 list.forEach(r=>{let b=document.createElement('button');b.className='card';b.innerHTML='<div class="art"><img alt=""><span class="tag">'+(r.demo?'示例记录':'观察记录')+'</span></div>'+cardCaption(r.id);b.querySelector('img').src=r.photo;$('records').append(b);b.onclick=()=>{show('<img alt="已保存的叶片" class="detailArt"><div class="body"><div class="eyebrow">'+(r.demo?'示例记录':'观察记录')+'</div><h2>'+plants[r.id].name+'</h2><i>'+plants[r.id].latin+'</i><p>'+plants[r.id].note+'</p><div class="recinfo">'+escapeHtml(r.date)+' · '+escapeHtml(r.location||'未填写地点')+'</div></div>');body.querySelector('img').src=r.photo}})}
function guide(){show('<div class="body"><div class="eyebrow">LEAF SCAN</div><h2>拍一片叶子</h2><p>将单片叶子置于纯色背景中央，拍全叶缘。当前可匹配银杏、鸡爪槭和垂柳。</p><div class="actions"><button class="primary" style="width:auto" id="take">打开相机</button><button class="light" id="choose">选择照片</button></div></div>');$('take').onclick=()=>$('cam').click();$('choose').onclick=()=>$('file').click()}
$('shoot').onclick=$('add').onclick=guide;$('album').onclick=()=>$('file').click();
function result(source,demo){let id=matchLeaf(source),c=document.createElement('canvas'),s=Math.min(1,640/Math.max(source.width,source.height));c.width=Math.max(1,Math.round(source.width*s));c.height=Math.max(1,Math.round(source.height*s));c.getContext('2d').drawImage(source,0,0,c.width,c.height);let photo=c.toDataURL('image/jpeg',.76);
 show('<img class="detailArt" alt="待识别的叶片"><div class="body"><div class="eyebrow">'+(demo?'示例叶片 · ':'')+'本地叶形匹配</div><h2>'+(id===null?'暂未辨认出叶形':'可能是'+plants[id].name)+'</h2><p>'+(id===null?'可换一张纯色背景的单叶照片，或手动选择已确认的植物。':plants[id].note)+'</p><label>确认植物<select id="species"><option value="">请选择</option>'+plants.map((p,i)=>'<option value="'+i+'">'+p.name+'</option>').join('')+'</select></label><label>发现地点（选填）<input id="place" maxlength="60" placeholder="例如：东校区图书馆旁"></label><button class="primary" id="save">加入我的植物园</button><p id="feedback" role="status"></p></div>');body.querySelector('img').src=photo;$('species').value=id===null?'':id;
 $('save').onclick=()=>{if($('species').value===''){$('feedback').textContent='请先确认植物种类。';return}let r={id:Number($('species').value),date:new Date().toLocaleDateString('zh-CN'),location:$('place').value.trim(),demo,photo};try{localStorage.setItem(key,JSON.stringify([r,...records()]))}catch{$('feedback').textContent='设备存储不可用或空间已满，本次记录未保存。';return}modal.close();location.hash='garden';route();$('toast').textContent='已加入我的植物园';setTimeout(()=>$('toast').textContent='',2400)}}
for(let input of [$('cam'),$('file')])input.onchange=async()=>{let f=input.files[0];input.value='';if(!f)return;let url=URL.createObjectURL(f);try{let img=new Image();img.src=url;await img.decode();result(img,false)}catch{show('<div class="body"><h2>照片读取失败</h2><p>请尝试 JPG、PNG 或 WebP 格式的照片。</p><button id="retry" class="light">重新选择</button></div>');$('retry').onclick=()=>$('file').click()}finally{URL.revokeObjectURL(url)}};
window.addEventListener('hashchange',route);route();
